package com.eventforge.notification;
import io.swagger.v3.oas.annotations.Operation;
import com.eventforge.common.CurrentUser; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService service; private final CurrentUser currentUser; public NotificationController(NotificationService service,CurrentUser currentUser){this.service=service;this.currentUser=currentUser;} @Operation(summary="List caller notifications") @GetMapping public Page<NotificationDto> list(Pageable pageable){return service.list(currentUser.id(),pageable);} @PatchMapping("/{id}/read") public NotificationDto read(@PathVariable UUID id){return service.markRead(id,currentUser.id());}}
